values ('aaaa0004-0000-4000-8000-000000000005', 'pt', 'br', 'Portuguese B2 — Upper Intermediate', 'A CEFR B2 upper-intermediate track in Brazilian Portuguese: defend an argument, follow complex media, write formal correspondence, and negotiate with nuance.', 'B2', 'work', 13, true, 'language', '{aaaa0004-0000-4000-8000-000000000003}')
